/**
 * Defines canonical official names, normalized emails and personal nickname limits.
 * Official identities are manager controlled; nicknames never identify company work.
 * Identifiers are generated by storage, never accepted as client-issued credentials.
 */
import { z } from "zod"
export const OFFICIAL_NAME_MIN = 2
export const OFFICIAL_NAME_MAX = 80

/**
 * Normalizes whitespace and capitalizes the first letter of each name segment.
 * @param value - Official name supplied by an authorized manager or administrator.
 * @returns string with Unicode-normalized title casing, preserving name separators.
 */
export function normalizeOfficialName(value: string): string {
  return value.normalize("NFKC").trim().replace(/\s+/gu, " ").toLocaleLowerCase("en-US").replace(/(^|[\s'-])\p{L}/gu, part => part.toLocaleUpperCase("en-US"))
}
/**
 * Canonicalizes an application account email without provider-specific alias folding.
 * @param value - Email from input or an authenticated Microsoft identity.
 * @returns string with surrounding whitespace removed and case normalized.
 */
export function normalizeEmail(value: string): string { return value.trim().normalize("NFKC").toLowerCase() }
export const emailSchema = z.string().transform(normalizeEmail).pipe(z.string().email().max(254))
export const officialNameSchema = z.string().transform(normalizeOfficialName).pipe(z.string().min(OFFICIAL_NAME_MIN).max(OFFICIAL_NAME_MAX).regex(/^[\p{L}\p{M}][\p{L}\p{M} '\-]*$/u, "Use letters, spaces, apostrophes or hyphens for an official name."))
export const employeeIdSchema = z.string().trim().max(64).refine(value=>!/[\p{Cc}\p{Cf}]/u.test(value),"Employee ID cannot contain control characters.")
// Nicknames preserve the user's chosen casing; the database reserves uniqueness.
export const nicknameSchema = z.string().trim().min(2).max(40).refine(value => !/[\p{Cc}\p{Cf}]/u.test(value), "Nickname contains hidden control characters.")
